            <div class="metadata-item">
                <span class="metadata-label">Submitted:</span> 02 October 2025
            </div>
            <div class="metadata-item">
                <span class="metadata-label">Last Updated:</span> 10 November 2025
            </div>
            <div class="metadata-item">
                <span class="metadata-label">Categories:</span> <span class="category">cs.SE</span>, <span class="category">cs.AI</span>, <span class="category">cs.CR</span>
            </div>
